DELETE FROM `quest_template_locale` WHERE `ID` = 286 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (286,'zhTW','歸還雕像','你把這個木桶從垃圾裡拖了出來，剛一打開它，一尊精心包裹在稻草中的銀制小刻像就掉了出來。這是一個頭髮很長的年輕聖騎士高舉戰錘的樣子。$B$B這一定就是米奈希爾刻像了!你必須馬上把它交還給米奈希爾港的卡爾·波蘭。','到濕地的米奈希爾港，將米奈希爾雕像還給卡爾·波蘭。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 292 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (292,'zhTW','帕雷斯之眼','打開箱子之後，你看到了一顆發黑的寶珠，它還在閃爍著可怕的光芒。這就是菲茲莫斯所說的寶藏:一顆被詛咒的帕雷斯之眼。$B$B把被詛咒的帕雷斯之眼交給住在米奈希爾港的矮人牧師戈羅林·鋼眉，請他驅除附著在它上面的詛咒。','到濕地的米奈希爾港，把被詛咒的帕雷斯之眼交給戈羅林·鋼眉。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 306 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (306,'zhTW','尋找挖掘隊','這太恐怖啦!我們剛剛發現了一些十分稀有的古物，而且正在把這些巨大的骸骨挖掘出來，這個時候，可怕的事就發生了，在我們反應過來之前，多到數不清的雜斑迅猛龍沖進了挖掘場，咬死了許多人!$B$B勇敢非凡的奧莫爾救下了我和勘察員，並一直把我們護送到了一處藏身之所。現在我們被徹底困在這裡了，逃也逃不出去，我們努力工作的成果也全毀了。$B$B給，把這封信帶回去交給我親愛的塔雷爾，我已經在信裡把事情跟他解釋清楚了。','到濕地的米奈希爾港，把麥琳的信件交給塔雷爾·石紋。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 632 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (632,'zhTW','薩多爾大橋','很顯然，可憐的老伊本瑟遭遇到了黑鐵矮人的伏擊，已經戰死了。但你突然注意到了他緊握著的拳頭中似乎有一張皺皺的羊皮紙。$B$B將這條令人沮喪的消息告訴拉格·加瑪森，並把你的發現報告給他。','到濕地的丹莫德向拉格·加瑪森回報，並將你在伊本瑟屍體上找到的羊皮紙交給他看看。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 5649 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (5649,'zhTW','部族的傳統','啊，朋友。我們之所以加入部落，是因為他們對我們很好。他們彼此忠誠，他們教會我們很多東西——比如榮耀。但是我們的一些傳統正在逐漸失去。也許獸人不認同我們所有的傳統，但是這並不妨礙我們秘密地延續它們。$B$B你知道這些，所以我派你去找剃刀嶺的泰金。她會向你教授更多關於我們歷史的東西，她會向你教授更多關於我們部族的東西。當你準備好了之後，就去找她。','與杜洛塔的泰金談一談。','','','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 11486 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (11486,'zhTW','美酒中的美酒','我知道像你這樣的$G小子:姑娘;最喜歡阻止衝突了，對吧？你想要讓你們的美酒節平平安安地辦完，不要出亂子。那麼我有一個提議……$B$B在這只酒杯中裝滿我們最棒的烈酒，然後把它交給鐵爐堡外的美酒節組織者，這樣我們黑鐵矮人也算是參加了這個節日！全艾澤拉斯最棒的烈酒來自這裡！黑石山的深處！不要忘了這一點！','將黑鐵啤酒杯交給丹莫洛的埃菲庫格·鐵桶。','','到丹莫洛找埃菲庫格·鐵桶。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 12278 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (12278,'zhTW','每月啤酒俱樂部','會員享有優惠。成為「每月啤酒俱樂部」的會員，表示你有管道獲得到最新、最青的啤酒。$B$B帶著你的「每月啤酒」俱樂部會員表格給拉金‧雷酒，他就在鐵爐堡的石火旅店中。','把「每月啤酒」俱樂部會員表格帶給拉金‧雷酒，他就在鐵爐堡的石火旅店中。','','到鐵爐堡的石火旅店找丹莫洛的拉金‧雷酒。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 13932 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (13932,'zhTW','又是一年美酒飄香時。','美酒節除了賽羊會外，還有一項傳統，那就是飲酒狂歡！如果你有時間的話，就將這張禮品券交給貝爾比吧。她就在美酒節營地的後面。要是你看不見她，沒關係，她一定會看見你的。$B$B無論如何，將禮品券交給她，你就能免費領到一隻美酒節酒杯。她還出售各種美酒哦。','在美酒節營地的貝爾比處兌換禮品券。','','去找丹莫洛的貝爾比。','','','','',0);
DELETE FROM `quest_template_locale` WHERE `ID` = 14167 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (14167,'zhTW','死者的感激','真高興能再次見到朋友和親人，不過也許我做得有些太誇張了……我已經吃光了他們為我準備的一切！$B$B能不能幫我一個忙，再給我拿來一些那種美味的悼念糕餅？我會非常感激你的……$B$B我想，那邊的查普曼正在出售食譜。','弄到悼念糕餅，並把它交給鐵爐堡墓地的歡快的矮人靈魂。$B$B你必須使用一朵橙菊，才能看到那個隱形的靈魂。','','到丹莫洛鐵爐堡大門找附近的歡快的矮人靈魂。','','','','',0);
